<h1>Booking Management</h1><table><tr><th>ID</th><th>User</th><th>Property</th><th>Check-in</th><th>Check-out</th><th>Status</th><th>Actions</th></tr><?php foreach($bookings as $b): ?><tr><td><?= e($b['booking_id']) ?></td><td><?= e($b['email']??current_user_email()) ?></td><td><?= e($b['title']) ?></td><td><?= e($b['check_in_date']) ?></td><td><?= e($b['check_out_date']) ?></td><td><span class='status <?= strtolower(e($b['booking_status'])) ?>'><?= e($b['booking_status']) ?></span></td><td><a href='<?= url('bookings/edit?id='.$b['booking_id']) ?>'>Edit</a> | <a onclick="return confirm('Delete booking?')" href='<?= url('bookings/delete?id='.$b['booking_id']) ?>'>Delete</a><?php if(in_array(current_user_role(),['Admin','Staff'])): ?> | <a href='<?= url('bookings/approve?id='.$b['booking_id']) ?>'>Approve</a> | <a href='<?= url('bookings/cancel?id='.$b['booking_id']) ?>'>Cancel</a><?php endif; ?></td></tr><?php endforeach; ?></table>
